          $f = $g > 0 ? self::clamp(($inner - $g + $sz * 0.5) / $fade, 0.22, 1) : 1; $wd = $sz * $f; $x = $xa < 50 ? $xa : $xa + $sz - $wd;
          for ($jj = 0; $jj * $sz < 100; $jj++) { if (fmod($i + $jj, 2) != 0) $o .= $rect($x, 7 + $jj * $sz - $sz, $wd, $sz, $p1); }
        }
        break;
      case 'sides': $sw = 1 + $w * 20; $o = $rect(-10, -5, 33 + $sw, 110, $p1) . $rect(77 - $sw, -5, 40, 110, $p1); break;
      case 'yoke': $o = ($tt ? "<path d=\"M-5,-5 H105 V23.5 Q50,33 -5,23.5 Z\" fill=\"$c2\"/>" : '') . "<path d=\"M-5,-5 H105 V21 Q50,30 -5,21 Z\" fill=\"$p1\"/>"; break;
      case 'fade': $o = "<defs><linearGradient id=\"$id-fade\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0.15\" stop-color=\"$p1\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"$p1\"/></linearGradient></defs><rect x=\"-10\" y=\"-5\" width=\"120\" height=\"110\" fill=\"url(#$id-fade)\"/>"; break;
      case 'pinhoops': $per = 88 / $count; for ($k = 0; $k <= $count; $k++) { $cy = 7 + ($k + 0.5) * $per; $o .= $rect(-10, $cy - 0.45, 120, 0.9, ($tt && $k % 2 === 1) ? $p2 : $p1); } break;
      case 'fan': $n = $count * 2 + 1; $sw = self::jn(self::r2(0.35 + $w * 0.9));
        for ($k = 0; $k < $n; $k++) { $xt = 10 + $k * 80 / ($n - 1); $xb = 50 + ($xt - 50) * 0.3;
          $o .= "<path d=\"M{$j($xt)},-2 Q{$j($xt+($xb-$xt)*0.15)},60 {$j($xb)},100\" fill=\"none\" stroke=\"$p1\" stroke-width=\"$sw\"/>"; }
        break;
      case 'offset': $n = min(5, $count); $sw = 0.8 + $w * 4; $x0 = 50 + $pos - $n * $sw / 2;
        for ($k = 0; $k < $n; $k++) $o .= $rect($x0 + $k * $sw, -5, $sw, 110, ($tt && $k % 2 === 1) ? $c2 : $p1); break;
      case 'wedges': $ww = 3 + $w * 14;
        $tri = function ($c, $e) use ($j, $ww) { $a = self::jn(21 - $e); $b = self::jn(79 + $e);
          return "<path d=\"M$a,20 L{$j(21+$ww+$e)},29 L$a,{$j(84+$e*2)} Z M$b,20 L{$j(79-$ww-$e)},29 L$b,{$j(84+$e*2)} Z\" fill=\"$c\"/>"; };
        $o = ($tt ? $tri($c2, 1.4) : '') . $tri($p1, 0); break;
      case 'swoosh': $off = $w * 22; $edge = "M{$j(66-$off*0.6)},-5 C{$j(72-$off*0.5)},30 {$j(75-$off*0.3)},62 105,{$j(96-$off*0.4)}";
        $o = "<path d=\"$edge L105,-5 Z\" fill=\"$p1\"/>";
        if ($tt) { $n = min(6, $count); for ($k = 0; $k < $n; $k++) $o .= "<path d=\"$edge\" fill=\"none\" stroke=\"$c2\" stroke-width=\".7\" transform=\"translate({$j(2.2+$k*2)} {$j(-0.6-$k*0.5)})\"/>"; }
        break;
      case 'shoulders': $sx = self::r2(33 + $w * 10); $sy = self::r2(30 + $w * 10);
        $pth = function ($e) use ($j, $sx, $sy) { return "M{$j($sx+$e)},-5 Q{$j($sx-4+$e)},18 {$j(20)},{$j($sy+$e)} L-5,{$j($sy+$e)} L-5,-5 Z M{$j(100-$sx-$e)},-5 Q{$j(104-$sx-$e)},18 80,{$j($sy+$e)} L105,{$j($sy+$e)} L105,-5 Z"; };
        $o = ($tt ? "<path d=\"{$pth(1.6)}\" fill=\"$c2\"/>" : '') . "<path d=\"{$pth(0)}\" fill=\"$p1\"/>"; break;
      case 'sidecurves': $kk = 2 + $w * 12;
        $pth = function ($e) use ($j, $kk) { return "M{$j(20-$e)},30 Q{$j(24+$kk*0.3+$e)},{$j(70)} {$j(28+$kk+$e)},100 L-5,100 L-5,30 Z M{$j(80+$e)},30 Q{$j(76-$kk*0.3-$e)},70 {$j(72-$kk-$e)},100 L105,100 L105,30 Z"; };
        $o = ($tt ? "<path d=\"{$pth(1.5)}\" fill=\"$c2\"/>" : '') . "<path d=\"{$pth(0)}\" fill=\"$p1\"/>"; break;
      case 'chevrons':
        $n = max(1, min(5, $count)); $t = 2.5 + $w * 7; $a = max(8, min(60, abs($angle))) * M_PI / 180;
        $tn = tan($a); $tv = $t / cos($a); $cols = [$c1, $c2, $c3]; $top = 24 + ($pos - 14) * 0.6;
        $yAt = function ($x, $k) use ($top, $tv, $tn) { return $top + $k * $tv - abs(50 - $x) * $tn; };
        for ($k = 0; $k < $n; $k++) { $c = $cols[$k % 3];
          if (empty($s['jagged'])) { $o .= "<path d=\"M-15,{$j($yAt(-15,$k))} L50,{$j($yAt(50,$k))} L115,{$j($yAt(115,$k))} L115,{$j($yAt(115,$k)+$tv)} L50,{$j($yAt(50,$k)+$tv)} L-15,{$j($yAt(-15,$k)+$tv)} Z\" fill=\"$c\"/>"; continue; }
          $seg = max(4, $tv * 1.5); $drop = $tv * 0.45;
          for ($i = 0; $i * $seg < 70; $i++) { $dy = ($i % 2) * $drop;
            foreach ([-1, 1] as $sg) { $xa = 50 + $sg * $i * $seg; $xb = 50 + $sg * ($i + 1) * $seg;
              $o .= "<path d=\"M{$j($xa)},{$j($yAt($xa,$k)+$dy)} L{$j($xb)},{$j($yAt($xb,$k)+$dy)} L{$j($xb)},{$j($yAt($xb,$k)+$dy+$tv)} L{$j($xa)},{$j($yAt($xa,$k)+$dy+$tv)} Z\" fill=\"$c\" stroke=\"$c\" stroke-width=\".15\"/>"; } }
        }
        break;
      case 'waves':
        $per = 88 / $count; $amp = $per * 0.32; $lam = 34; $sw = self::jn(self::r2(max(0.5, $per * $w))); $tilt = self::clamp($angle, -40, 40);
        $g = '';
        for ($k = -3; $k <= $count + 3; $k++) { $cy = 7 + ($k + 0.5) * $per; $d = "M-40,{$j($cy)}";
          for ($x = -40, $i = 0; $x < 140; $x += $lam / 2, $i++) $d .= ($i ? 'T' : 'Q' . $j($x + $lam / 4) . ',' . $j($cy - $amp * 2)) . ' ' . $j($x + $lam / 2) . ',' . $j($cy);
          $g .= "<path d=\"$d\" fill=\"none\" stroke=\"" . (($tt && abs($k) % 2 === 1) ? $c2 : $c1) . "\" stroke-width=\"$sw\"/>"; }
        $o = "<g transform=\"rotate({$j($tilt)} 50 50)\">$g</g>"; break;
      case 'cross':
        $t = 4 + $w * 12; $vx = 50 + self::clamp($pos, -24, 24); $hy = 30 + self::clamp(self::num(isset($s['vpos']) ? $s['vpos'] : 0, 0), -18, 40); $e = 1.8;
        $bars = function ($c, $x) use ($rect, $vx, $hy, $t) { return $rect($vx - $t / 2 - $x, -5, $t + 2 * $x, 110, $c) . $rect(-10, $hy - $t / 2 - $x, 120, $t + 2 * $x, $c); };
        $o = ($tt ? $bars($c2, $e) : '') . $bars($c1, 0); break;
      case 'burst':
        $n = max(4, $count * 4); $sw = self::jn(self::r2(0.25 + $w * 1.4)); $cy = 38 + ($pos - 14) * 0.8; $cols = $tt ? [$c1, $c2, $c3] : [$c1];
        for ($k = 0; $k < $n; $k++) { $a = ($k + 0.5) / $n * M_PI * 2;
          $o .= "<line x1=\"50\" y1=\"{$j($cy)}\" x2=\"{$j(50+cos($a)*130)}\" y2=\"{$j($cy+sin($a)*130)}\" stroke=\"" . $cols[$k % count($cols)] . "\" stroke-width=\"$sw\"/>"; }
        break;
      case 'rings':
        $sp = 38 / $count; $cy = 48 + ($pos - 14) * 0.8; $sw = self::jn(self::r2(max(0.4, $sp * $w)));
        for ($k = 1; $k * $sp < 80; $k++) $o .= "<circle cx=\"50\" cy=\"{$j($cy)}\" r=\"{$j($k*$sp)}\" fill=\"none\" stroke=\"" . (($tt && $k % 2 === 0) ? $c2 : $c1) . "\" stroke-width=\"$sw\"/>";
        break;
      case 'zigzag':
        $per = 88 / $count; $amp = $per * 0.75; $lam = max(3, $per * 0.8); $sw = self::jn(self::r2(max(0.4, $per * $w * 0.6)));
        for ($k = -2; $k <= $count + 2; $k++) { $cy = 7 + ($k + 0.5) * $per; $d = "M-10,{$j($cy+$amp/2)}";
          for ($x = -10, $i = 0; $x < 115; $x += $lam / 2, $i++) $d .= ' L' . $j($x + $lam / 2) . ',' . $j($cy + ($i % 2 ? $amp / 2 : -$amp / 2));
          $o .= "<path d=\"$d\" fill=\"none\" stroke=\"" . (($tt && abs($k) % 2 === 1) ? $c2 : $c1) . "\" stroke-width=\"$sw\" stroke-linejoin=\"miter\" stroke-miterlimit=\"10\"/>"; }
        break;
      case 'panel':
        $bw = 4 + $w * 24; $x0 = 50 + self::clamp($pos, -24, 24) - $bw / 2; $g = self::clamp(self::num($s['gap'], 0), 0, 30);
        if ($tt) $o .= $rect($x0 + $bw - 0.2, -5, 2.2, 110, $c2);
        $o .= $rect($x0, -5, $bw, 110, $p1);
        if ($g > 0) $o .= $rect($x0 - $g * 0.6 - 0.8, -5, 0.8, 110, $p1);
        break;
      case 'peaks':
        $n = max(1, min(6, $count)); $P = 74 / $n; $sw = 1.5 + $w * 9; $hy = 40 + ($pos - 14) * 0.8;
        $amp = tan(self::clamp(abs($angle), 10, 70) * M_PI / 180) * $P / 2;
        $d = "M8,{$j($hy+$amp)}"; for ($i = 0; $i < $n; $i++) { $xa = 13 + $i * $P; $d .= ' L' . $j($xa + $P / 2) . ',' . $j($hy) . ' L' . $j($xa + $P) . ',' . $j($hy + $amp); } $d .= ' L92,' . $j($hy + $amp);
        $o = "<path d=\"$d\" fill=\"none\" stroke=\"$c1\" stroke-width=\"{$j($sw)}\" stroke-linejoin=\"miter\" stroke-miterlimit=\"12\"/>";
        if ($tt) { $vx = $n % 2 === 0 ? 50 : 50 + $P / 2; $vy = $n % 2 === 0 ? $hy + $amp - $sw * 1.1 : $hy - $sw * 1.1; $r = max(1.2, $sw * 0.45);
          $o .= "<path d=\"M{$j($vx)},{$j($vy-$r*1.4)} L{$j($vx+$r)},{$j($vy)} L{$j($vx)},{$j($vy+$r*1.4)} L{$j($vx-$r)},{$j($vy)} Z\" fill=\"$c2\"/>"; }
        break;
      case 'raglan': $o = "<path d=\"M37,-5 L37,9 L22,31 L-5,31 L-5,-5 Z M63,-5 L63,9 L78,31 L105,31 L105,-5 Z\" fill=\"$p1\"/>" . ($tt ? "<path d=\"M37,9 L22,31 M63,9 L78,31\" stroke=\"$c2\" stroke-width=\"1.2\" fill=\"none\"/>" : ''); break;
    }
    if (!empty($s['flip']) && in_array($s['pattern'], self::$D['FLIPPABLE'], true) && $o !== '') $o = "<g transform=\"matrix(-1 0 0 1 100 0)\">$o</g>";
    return $o;
  }

  /* ---------- mottling ---------- */
  static function mottleTile($s, $pid) {
    $style = in_array($s['mottle'], self::$D['MOTTLE_IDS'], true) ? $s['mottle'] : 'off';
    if ($style === 'off') return '';
    $j = function ($v) { return self::jn(self::r2($v)); };
    $c = self::safeColor($s['mottleColor'], self::$D['DEFAULT']['mottleColor']); $sc = self::clamp(self::num($s['mottleScale'], 100), 40, 250) / 100;
    $seed = ((int)self::clamp(self::round(self::num($s['mottleSeed'], 7)), 1, 99999) * 2654435761) & 0xffffffff;
    $rnd = self::mulberry($seed);
    $T = 0; $TH = 0; $body = '';
    $dot = function ($x, $y, $r, $op) use (&$T, $j) { $o = '';
      foreach ([-$T, 0, $T] as $ox) foreach ([-$T, 0, $T] as $oy) { $X = $x + $ox; $Y = $y + $oy;
        if ($X + $r < 0 || $Y + $r < 0 || $X - $r > $T || $Y - $r > $T) continue;
        $o .= "<circle cx=\"{$j($X)}\" cy=\"{$j($Y)}\" r=\"{$j($r)}\"" . ($op < 1 ? " fill-opacity=\"{$j($op)}\"" : '') . '/>'; }
      return $o; };
    $dia = function ($cx, $cy, $r) use ($j) { return "M{$j($cx)},{$j($cy-$r)}L{$j($cx+$r)},{$j($cy)}L{$j($cx)},{$j($cy+$r)}L{$j($cx-$r)},{$j($cy)}Z"; };
    if ($style === 'speckle') { $T = 12 * $sc;
      for ($i = 0; $i < 34; $i++) { $a = $rnd() * $T; $b = $rnd() * $T; $r = (0.18 + $rnd() * 0.5) * $sc; $op = 0.45 + $rnd() * 0.55; $body .= $dot($a, $b, $r, $op); }
      $body = "<g fill=\"$c\">$body</g>"; }
    elseif ($style === 'blotch') { $T = 28 * $sc;
      for ($i = 0; $i < 11; $i++) { $bx = $rnd() * $T; $by = $rnd() * $T; $br = (1.8 + $rnd() * 3.4) * $sc; $op = 0.18 + $rnd() * 0.22;
        for ($k = 0; $k < 3; $k++) { $r = $br * (0.55 + $rnd() * 0.45); $x = $bx + ($rnd() - 0.5) * $br; $y = $by + ($rnd() - 0.5) * $br;
          foreach ([1, 0.72, 0.45] as $f) $body .= $dot($x, $y, $r * $f, $op); } }
      for ($i = 0; $i < 18; $i++) { $a = $rnd() * $T; $b = $rnd() * $T; $r = (0.25 + $rnd() * 0.5) * $sc; $op = 0.35 + $rnd() * 0.4; $body .= $dot($a, $b, $r, $op); }
      $body = "<g fill=\"$c\">$body</g>"; }
    elseif ($style === 'lattice') { $T = 11 * $sc; $h = $T / 2; $sw = self::jn(self::r2($T * 0.065));
      $body = "<path d=\"{$dia($h,$h,$T*0.44)} {$dia($h,$h,$T*0.29)}\" fill=\"none\" stroke=\"$c\" stroke-width=\"$sw\"/>" .
        "<path d=\"{$dia($h,$h,$T*0.12)} {$dia(0,0,$T*0.11)} {$dia($T,0,$T*0.11)} {$dia(0,$T,$T*0.11)} {$dia($T,$T,$T*0.11)}\" fill=\"$c\"/>" .
        "<g fill=\"$c\"><circle cx=\"{$j($h)}\" cy=\"0\" r=\"{$j($T*0.04)}\"/><circle cx=\"{$j($h)}\" cy=\"{$j($T)}\" r=\"{$j($T*0.04)}\"/><circle cx=\"0\" cy=\"{$j($h)}\" r=\"{$j($T*0.04)}\"/><circle cx=\"{$j($T)}\" cy=\"{$j($h)}\" r=\"{$j($T*0.04)}\"/></g>"; }
    elseif ($style === 'weave') { $T = 4 * $sc; $sw = self::jn(self::r2($T * 0.16));
      $body = "<path d=\"M0,{$j($T*0.25)}H{$j($T*0.5)}M{$j($T*0.5)},{$j($T*0.75)}H{$j($T)}M{$j($T*0.25)},{$j($T*0.5)}V{$j($T)}M{$j($T*0.75)},0V{$j($T*0.5)}\" stroke=\"$c\" stroke-width=\"$sw\" fill=\"none\" stroke-linecap=\"square\"/>"; }
    elseif ($style === 'zebra') { $T = 26 * $sc; $n = 5; $steps = 18;
      for ($k = 0; $k < $n; $k++) {
        $bx = ($k + $rnd() * 0.4) * $T / $n; $amp = (1.2 + $rnd() * 2.2) * $sc; $ph = $rnd() * M_PI * 2; $w0 = (0.5 + $rnd() * 0.9) * $sc; $wv = (0.3 + $rnd() * 0.7) * $sc; $ph2 = $rnd() * M_PI * 2;
        $cxAt = function ($y) use ($bx, $amp, $T, $ph, $ph2) { return $bx + $amp * sin(2 * M_PI * $y / $T + $ph) + $amp * 0.4 * sin(4 * M_PI * $y / $T + $ph2); };
        $hwAt = function ($y) use ($sc, $w0, $wv, $T, $ph2) { return max(0.12 * $sc, $w0 + $wv * sin(2 * M_PI * $y / $T * 2 + $ph2)); };
        foreach ([-$T, 0, $T] as $ox) { $L = ''; $R = '';
          for ($i = 0; $i <= $steps; $i++) { $y = $i * $T / $steps; $L .= ($i ? 'L' : 'M') . $j($cxAt($y) - $hwAt($y) + $ox) . ',' . $j($y); }
          for ($i = $steps; $i >= 0; $i--) { $y = $i * $T / $steps; $R .= 'L' . $j($cxAt($y) + $hwAt($y) + $ox) . ',' . $j($y); }
          $body .= "<path d=\"$L{$R}Z\"/>"; } }
      $body = "<g fill=\"$c\">$body</g>"; }
    elseif ($style === 'leaves') { $T = 7 * $sc; $TH = $T * 0.6; $h = $T / 2; $cy = $TH * 0.5; $dx = $T * 0.19; $rx = self::jn(self::r2($T * 0.12)); $ry = self::jn(self::r2($T * 0.3));
      $body = "<g fill=\"$c\"><ellipse cx=\"{$j($h-$dx)}\" cy=\"{$j($cy)}\" rx=\"$rx\" ry=\"$ry\" transform=\"rotate(-42 {$j($h-$dx)} {$j($cy)})\"/><ellipse cx=\"{$j($h+$dx)}\" cy=\"{$j($cy)}\" rx=\"$rx\" ry=\"$ry\" transform=\"rotate(42 {$j($h+$dx)} {$j($cy)})\"/></g>"; }
    elseif ($style === 'streaks') { $T = 24 * $sc;
      for ($i = 0; $i < 16; $i++) {
        $L = (4 + $rnd() * 9) * $sc; $h = (0.25 + $rnd() * 0.6) * $sc; $x = $rnd() * $T; $y = $h + $rnd() * ($T - 2 * $h); $k = 0.12 + $rnd() * 0.2;
        foreach ([-$T, 0, $T] as $ox) { $X = $x + $ox; if ($X > $T || $X + $L < 0) continue;
          $body .= "<path d=\"M{$j($X)},{$j($y)} L{$j($X+$L*$k)},{$j($y-$h)} L{$j($X+$L)},{$j($y)} L{$j($X+$L*$k)},{$j($y+$h)} Z\"/>"; } }
      $body = "<g fill=\"$c\">$body</g>"; }
    return "<pattern id=\"$pid\" patternUnits=\"userSpaceOnUse\" x=\"50\" y=\"7\" width=\"{$j($T)}\" height=\"{$j($TH ? $TH : $T)}\">$body</pattern>";
  }

  /* ---------- render (badges are not drawn: random shirts have none) ---------- */
  static function render($s, $size) {
    $D = self::$D['DEFAULT']; $j = function ($v) { return self::jn(self::r2($v)); };
    $id = 'kit' . base_convert((string)(++self::$uid), 10, 36);
    $col = function ($k) use ($s, $D) { return self::safeColor(isset($s[$k]) ? $s[$k] : null, $D[$k]); };
    $base = $col('base'); $outline = $col('outline'); $sleeve = $col('sleeve'); $cuffColor = $col('cuffColor');
    $cuffStripeColor = $col('cuffStripeColor'); $collarColor = $col('collarColor'); $collarStripeColor = $col('collarStripeColor');
    $shColor = $col('shColor'); $starColor = $col('starColor'); $numColor = $col('numColor'); $numStroke = $col('numStroke');
    $outlineW = self::num($s['outlineW'], 1); $numSize = self::num($s['numSize'], 14);
    $exportSize = $size !== null && $size !== '' ? self::num($size, 0) : 0;
    $G = self::geom($s); $body = $G['body']; $SLEEVES = $G['sleeves']; $CUFFS = $G['cuffs'];
    $NECK = self::$D['NECK']; $neck = isset($NECK[$s['collar']]) ? $NECK[$s['collar']] : $NECK['round'];
    $sh = self::clamp(self::num($s['shading'], 40), 0, 100) / 100;
    $rawPat = self::patternSVG($s, $id);
    $pat = $rawPat !== '' ? "<g transform=\"{$G['patT']}\">$rawPat</g>" : '';
    $sleeveFill = !empty($s['patternSleeves']) ? $base : $sleeve;
    $o = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{$G['viewBox']}\"" . ($exportSize ? ' width="' . self::jn($exportSize) . '" height="' . self::jn($exportSize) . '"' : '') . '>';
    $o .= "<defs><clipPath id=\"$id-b\"><path d=\"$body\"/></clipPath><clipPath id=\"$id-s\"><path d=\"$SLEEVES\"/></clipPath><clipPath id=\"$id-a\"><path d=\"$body $SLEEVES\"/></clipPath>";
    $o .= "<linearGradient id=\"$id-sh\" gradientUnits=\"userSpaceOnUse\" x1=\"{$j($G['x0'])}\" y1=\"0\" x2=\"{$j($G['x1'])}\" y2=\"0\"><stop offset=\"0\" stop-color=\"#000\" stop-opacity=\"{$j($sh*.55)}\"/><stop offset=\".28\" stop-color=\"#000\" stop-opacity=\"0\"/><stop offset=\".5\" stop-color=\"#fff\" stop-opacity=\"{$j($sh*.22)}\"/><stop offset=\".72\" stop-color=\"#000\" stop-opacity=\"0\"/><stop offset=\"1\" stop-color=\"#000\" stop-opacity=\"{$j($sh*.55)}\"/></linearGradient></defs>";
    $mtile = self::mottleTile($s, $id . '-mt'); $mOp = self::jn(self::r2(self::clamp(self::num($s['mottleStrength'], 45), 5, 100) / 100));
    $mottleLayer = function ($clip) use ($mtile, $id, $mOp) { return $mtile !== '' ? "<rect x=\"-40\" y=\"-20\" width=\"180\" height=\"160\" fill=\"url(#$id-mt)\" fill-opacity=\"$mOp\" clip-path=\"url(#$clip)\"/>" : ''; };
    if ($mtile !== '') $o .= "<defs>$mtile</defs>";
    $o .= "<path d=\"M31,7 Q50,10.5 69,7 $neck Z\" fill=\"$base\"/><path d=\"M31,7 Q50,10.5 69,7 $neck Z\" fill=\"#000\" fill-opacity=\".32\"/>";
    $o .= "<path d=\"$SLEEVES\" fill=\"$sleeveFill\"/>";
    if (!empty($s['patternSleeves']) && $pat !== '') $o .= "<g clip-path=\"url(#$id-s)\">" . str_replace("$id-fade", "$id-fade2", $pat) . '</g>';
    if (!empty($s['mottleSleeves'])) $o .= $mottleLayer("$id-s");
    if (!empty($s['cuff'])) { $o .= "<path d=\"$CUFFS\" fill=\"$cuffColor\"/>";
      if (!empty($s['cuffStripe'])) $o .= "<path d=\"{$G['cuffLine']}\" stroke=\"$cuffStripeColor\" stroke-width=\"" . self::jn($G['cuffLineW']) . "\" fill=\"none\"/>"; }
    $o .= "<path d=\"$body\" fill=\"$base\"/>";
    if ($pat !== '') $o .= "<g clip-path=\"url(#$id-b)\">$pat</g>";
    $o .= $mottleLayer("$id-b");
    if (!empty($s['shStripes'])) {
      $line = function ($k, $side) use ($G, $shColor, $j) {
        $pts = implode(' ', array_map(function ($q) use ($j) { return $j($q[0]) . ',' . $j($q[1]); }, $side < 0 ? $G['shoulderL'] : $G['shoulderR']));
        return "<polyline points=\"$pts\" fill=\"none\" stroke=\"$shColor\" stroke-width=\".8\" stroke-linejoin=\"round\" transform=\"translate({$j($side*-0.55*($k+1)*1.3)} {$j(1.05*($k+1)*1.3)})\"/>"; };
