      if (!empty($s['collarStripe'])) $o .= "<path d=\"M69,7 $neck\" fill=\"none\" stroke=\"$collarStripeColor\" stroke-width=\"" . ($s['collar'] === 'crew' ? '1.1' : '0.85') . "\" stroke-linejoin=\"round\"/>";
