  /* ---------- kit validation (same rules as sanitizeKit in kit-engine.js) ---------- */
  static function sanitizeKit($raw) {
    $d = self::$D['DEFAULT']; $out = $d;
    foreach (self::$D['COLOR_KEYS'] as $k) if (array_key_exists($k, $raw)) $out[$k] = self::safeColor($raw[$k], $d[$k]);
    foreach (['twoTone', 'center', 'jagged', 'flip', 'shStripes', 'patternSleeves', 'cuff', 'cuffStripe', 'collarStripe', 'numEdge', 'mottleSleeves'] as $k) if (array_key_exists($k, $raw)) $out[$k] = (bool)$raw[$k];
