    $out['shirtLen'] = self::clamp($g('shirtLen'), 70, 130);
    $out['shirtWid'] = self::clamp($g('shirtWid'), 70, 130);
    $out['sleeveLen'] = self::clamp($g('sleeveLen'), 50, 140);
    $out['sleeveWid'] = self::clamp($g('sleeveWid'), 50, 140);
    $out['cuffWid'] = self::clamp($g('cuffWid'), 50, 150);
    $out['count'] = self::clamp(self::round($g('count')), 1, 12);
    $out['width'] = self::clamp($g('width'), 5, 100);
    $out['angle'] = self::clamp($g('angle'), -90, 90);
    $out['pos'] = self::clamp($g('pos'), -20, 40);
    $out['gap'] = self::clamp($g('gap'), 0, 30);
    $out['vpos'] = self::clamp($g('vpos'), -18, 40);
    $out['stars'] = self::clamp(self::round($g('stars')), 0, 10);
    $out['starSize'] = self::clamp($g('starSize'), 1, 12);
    $out['starGap'] = self::clamp($g('starGap'), 0, 4);
    $out['starDy'] = self::clamp($g('starDy'), -10, 10);
    $out['numSize'] = self::clamp($g('numSize'), 6, 40);
