    $out['makerPos'] = $in('makerPos', ['L', 'C', 'R', 'M', 'B']);
    $out['makerSize'] = self::clamp($g('makerSize'), 3, 30);
    $out['makerDx'] = self::clamp($g('makerDx', 0), -12, 12);
    $out['makerDy'] = self::clamp($g('makerDy', 0), -12, 20);
    $out['mottle'] = $in('mottle', self::$D['MOTTLE_IDS']);
    $out['mottleStrength'] = self::clamp($g('mottleStrength'), 5, 100);
    $out['mottleScale'] = self::clamp($g('mottleScale'), 40, 250);
    $out['mottleSeed'] = self::clamp(self::round($g('mottleSeed')), 1, 99999);
    $out['pattern'] = $in('pattern', self::$D['PATTERN_IDS']);
    $out['collar'] = $in('collar', ['round', 'crew', 'v', 'polo']);
    $out['starPos'] = $in('starPos', ['crest', 'L', 'C', 'R', 'M', 'B']);
    $out['starLayout'] = $in('starLayout', ['row', 'stack', 'arc']);
    $out['numPos'] = $in('numPos', ['L', 'C', 'R', 'M', 'B']);
