        'size' => self::clamp(self::num(isset($L['size']) ? $L['size'] : null, $dl['size']), 4, 40),
        'dx' => self::clamp(self::num(isset($L['dx']) ? $L['dx'] : null, 0), -12, 12), 'dy' => self::clamp(self::num(isset($L['dy']) ? $L['dy'] : null, 0), -12, 20),
        'invert' => !empty($L['invert']), 'recolor' => !empty($L['recolor']), 'tint' => self::safeColor(isset($L['tint']) ? $L['tint'] : null, '#ffffff')]; }
