    $legible = function ($bg) use ($contrast) { return $contrast('#ffffff', $bg) >= $contrast('#111418', $bg) ? '#ffffff' : '#111418'; };
    $base = $colour(); $p1 = $against($base, 1.8); $p2 = $against($p1, 1.6); $p3 = $against($base, 1.6); $trim = $pick([$p1, $p2, $legible($base)]);
