    $k['shirtLen'] = $int(92, 110); $k['shirtWid'] = $int(90, 110); $k['sleeveLen'] = $int(75, 125); $k['sleeveWid'] = $int(78, 112); $k['cuffWid'] = $step(50, 150, 5);
    $k['pattern'] = $chance(.12) ? 'plain' : $pick($patterns); $k['p1'] = $p1; $k['p2'] = $p2; $k['p3'] = $p3;
    $k['twoTone'] = $chance(.4); $k['count'] = $int(2, 10); $k['width'] = $int(10, 80); $k['angle'] = $chance(.5) ? $pick([-35, -20, 0, 20, 35]) : $int(-45, 45);
    $k['center'] = $chance(.5); $k['pos'] = $step(-10, 24, .5); $k['vpos'] = $step(-10, 24, .5); $k['gap'] = $int(0, 14); $k['jagged'] = $chance(.3); $k['flip'] = $chance(.5);
