  /* ---------- the file ---------- */
  static function jsonValue($v) {                // whole-number floats as integers, like JSON.stringify
    if (is_array($v)) { foreach ($v as $k => $x) $v[$k] = self::jsonValue($x); return $v; }
    if (is_float($v) && is_finite($v) && floor($v) == $v && abs($v) < 1e15) return (int)$v;
